	}
	if s.Name != MiniMaxAPIKeyEnv {
		return "", ErrCredentialUnavailable
	}
	value := os.Getenv(s.Name)
	if strings.TrimSpace(value) == "" {
		return "", ErrCredentialUnavailable
	}
	return value, nil
}

