}

func (s *Service) acquireCapacity(ctx context.Context) (func(), error) {
	if err := acquire(ctx, s.executions); err != nil {
		return nil, err
	}
	if err := acquire(ctx, s.worktrees); err != nil {
		release(s.executions)
		return nil, err
	}
	return func() {
		release(s.worktrees)
		release(s.executions)
	}, nil
}
